function bestDigitProduct(n: number): number {
  const ds = String(n).split("").map(Number);
  let best = 0;
  for (let i = 0; i < ds.length; i++)
    for (let j = i + 1; j < ds.length; j++) best = Math.max(best, ds[i] * ds[j]);
  return best;
}

