function bestDigitProduct(n: number): number {
  let first = -1, second = -1;
  while (n > 0) {
    const d = n % 10;
    n = Math.floor(n / 10);
    if (d >= first) {
      second = first;
      first = d;
    } else if (d > second) {
      second = d;
    }
  }
  return first * second;
}

